import React, { useState, useEffect } from 'react';
import { useParams, useLocation, useNavigate } from 'react-router-dom';
import { Box, Typography, TextField, Button, Avatar, CircularProgress, Divider, IconButton } from '@mui/material';
import { Send as SendIcon, ArrowBack as ArrowBackIcon } from '@mui/icons-material';
import axios from 'axios';
import { useAuth } from '../context/AuthContext';

const CommentsPage = () => {
  const { id } = useParams();
  const location = useLocation();
  const navigate = useNavigate();
  const { user } = useAuth();
  
  const [article, setArticle] = useState(location.state?.article || null);
  const [comments, setComments] = useState([]);
  const [newComment, setNewComment] = useState('');
  const [loading, setLoading] = useState(!article);
  const [submitting, setSubmitting] = useState(false);

  useEffect(() => {
    const fetchArticleAndComments = async () => {
      try {
        setLoading(true);
        
        // If we don't have the article data, fetch it
        if (!article) {
          const articleRes = await axios.get(`/api/news/${id}`);
          setArticle(articleRes.data);
        }
        
        // Fetch comments
        const commentsRes = await axios.get(`/api/comments/article/${id}`);
        setComments(commentsRes.data);
      } catch (err) {
        console.error('Error fetching data:', err);
      } finally {
        setLoading(false);
      }
    };

    fetchArticleAndComments();
  }, [id, article]);

  const handleSubmitComment = async (e) => {
    e.preventDefault();
    if (!newComment.trim() || !user) return;

    try {
      setSubmitting(true);
      const res = await axios.post('/api/comments', {
        articleId: id,
        content: newComment,
      });
      
      setComments([...comments, res.data]);
      setNewComment('');
    } catch (err) {
      console.error('Error submitting comment:', err);
    } finally {
      setSubmitting(false);
    }
  };

  if (loading) {
    return (
      <Box display="flex" justifyContent="center" alignItems="center" minHeight="60vh">
        <CircularProgress />
      </Box>
    );
  }

  if (!article) {
    return (
      <Box textAlign="center" p={4}>
        <Typography variant="h6">Article not found</Typography>
      </Box>
    );
  }

  return (
    <Box>
      <Box display="flex" alignItems="center" mb={3}>
        <IconButton onClick={() => navigate(-1)} sx={{ mr: 2 }}>
          <ArrowBackIcon />
        </IconButton>
        <Typography variant="h4" component="h1">
          {article.title}
        </Typography>
      </Box>
      
      <Box mb={4}>
        <Typography variant="subtitle1" color="textSecondary" paragraph>
          {article.description}
        </Typography>
      </Box>
      
      <Divider sx={{ my: 3 }} />
      
      <Box mb={4}>
        <Typography variant="h6" gutterBottom>
          Comments ({comments.length})
        </Typography>
        
        {user ? (
          <Box component="form" onSubmit={handleSubmitComment} display="flex" mb={3}>
            <Avatar 
              src={user.avatar} 
              alt={user.name} 
              sx={{ width: 40, height: 40, mr: 2 }}
            />
            <TextField
              fullWidth
              variant="outlined"
              placeholder="Write a comment..."
              value={newComment}
              onChange={(e) => setNewComment(e.target.value)}
              sx={{
                '& .MuiOutlinedInput-root': {
                  borderRadius: '24px',
                  backgroundColor: 'background.paper',
                },
                '& .MuiOutlinedInput-input': {
                  py: 1.5,
                },
              }}
            />
            <Button
              type="submit"
              color="primary"
              variant="contained"
              disabled={!newComment.trim() || submitting}
              sx={{ ml: 2, borderRadius: '24px', px: 3, minWidth: '100px' }}
              startIcon={submitting ? <CircularProgress size={20} color="inherit" /> : <SendIcon />}
            >
              {submitting ? 'Posting...' : 'Post'}
            </Button>
          </Box>
        ) : (
          <Box mb={3} textAlign="center">
            <Typography variant="body2" color="textSecondary">
              Please log in to leave a comment.
            </Typography>
          </Box>
        )}
        
        {comments.length === 0 ? (
          <Box textAlign="center" py={4}>
            <Typography variant="body1" color="textSecondary">
              No comments yet. Be the first to comment!
            </Typography>
          </Box>
        ) : (
          <Box>
            {comments.map((comment) => (
              <Box key={comment._id} mb={3}>
                <Box display="flex" alignItems="center" mb={1}>
                  <Avatar 
                    src={comment.user?.avatar} 
                    alt={comment.user?.name}
                    sx={{ width: 32, height: 32, mr: 1.5 }}
                  />
                  <Typography variant="subtitle2" fontWeight={500}>
                    {comment.user?.name || 'Anonymous'}
                  </Typography>
                  <Typography variant="caption" color="textSecondary" sx={{ ml: 1.5 }}>
                    {new Date(comment.createdAt).toLocaleDateString()}
                  </Typography>
                </Box>
                <Typography variant="body1" sx={{ pl: '48px' }}>
                  {comment.content}
                </Typography>
                <Divider sx={{ mt: 2 }} />
              </Box>
            ))}
          </Box>
        )}
      </Box>
    </Box>
  );
};

export default CommentsPage;
